  'JST 戦略的創造研究推進事業 (さきがけ)',
  'さきがけ2023',
  2023,
  'awarded',
  'https://www.jst.go.jp/kisoken/presto/application/2023/230919/230919presto.pdf',
  '研究領域: ' || s.area
from ins i join src s on s.title = i.title;
